<?php
namespace Opencart\Catalog\Model\Extension\Sixmoments\Shipping;
class Dpd extends \Opencart\System\Engine\Model { public function getQuote(array $address): array {if(!$this->config->get('shipping_sixmoments_dpd_status'))return[];$cost=(float)$this->config->get('shipping_sixmoments_dpd_cost');$quote=['dpd'=>['code'=>'dpd.dpd','name'=>'DPD · 1–7 business days','cost'=>$cost,'tax_class_id'=>(int)$this->config->get('shipping_sixmoments_dpd_tax_class_id'),'text'=>$this->currency->format($this->tax->calculate($cost,(int)$this->config->get('shipping_sixmoments_dpd_tax_class_id'),$this->config->get('config_tax')),$this->session->data['currency'])]];return['code'=>'dpd','name'=>'DPD','quote'=>$quote,'sort_order'=>(int)$this->config->get('shipping_sixmoments_dpd_sort_order'),'error'=>false];} }
